const DAYS: readonly Day[] = ["Mo", "Tu", "We", "Th", "Fr", "Sa", "Su"];

type TokenKind = "word" | "time" | "-" | "," | ";" | "other" | "end";

interface Token {
  kind: TokenKind;
  text: string;
  column: number;
}

function isLetter(ch: string): boolean {
  return /^\p{L}$/u.test(ch);
}

function isTimeChar(ch: string): boolean {
  return (ch >= "0" && ch <= "9") || ch === ":";
}

function tokenize(text: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;
  while (i < text.length) {
    const ch = String.fromCodePoint(text.codePointAt(i)!);
    const column = i + 1;
    if (ch === " ") {
      i++;
    } else if (ch === "-" || ch === "," || ch === ";") {
      tokens.push({ kind: ch, text: ch, column });
      i++;
    } else if (isLetter(ch) || isTimeChar(ch)) {
      const test = isLetter(ch) ? isLetter : isTimeChar;
      let j = i;
      while (j < text.length) {
        const c = String.fromCodePoint(text.codePointAt(j)!);
        if (!test(c)) break;
        j += c.length;
      }
      tokens.push({ kind: test === isLetter ? "word" : "time", text: text.slice(i, j), column });
      i = j;
    } else {
      tokens.push({ kind: "other", text: ch, column });
      i += ch.length;
    }
  }
  tokens.push({ kind: "end", text: "", column: text.length + 1 });
  return tokens;
}

/** Minutes since midnight, or null if the token is not a valid TIME. */
function timeToMinutes(text: string, isEnd: boolean): number | null {
  const match = /^(\d\d):(\d\d)$/.exec(text);
  if (!match) return null;
  const hours = Number(match[1]);
  const minutes = Number(match[2]);
  if (hours === 24 && minutes === 0) return isEnd ? 24 * 60 : null;
  if (hours > 23 || minutes > 59) return null;
  return hours * 60 + minutes;
}

function describe(token: Token): string {
  return token.kind === "end" ? "end of text" : `"${token.text}"`;
}

class Parser {
  private readonly tokens: Token[];
  private pos = 0;

  constructor(text: string) {
    this.tokens = tokenize(text);
  }

  private peek(): Token {
    return this.tokens[this.pos];
  }

  private next(): Token {
    const token = this.tokens[this.pos];
    if (token.kind !== "end") this.pos++;
    return token;
  }

  private unexpected(token: Token, expected: string): never {
    throw new OpeningHoursError("UNEXPECTED", token.column, `Expected ${expected} but found ${describe(token)}`);
  }

  parse(): WeeklyHours {
    const result = Object.fromEntries(DAYS.map((day) => [day, []])) as unknown as WeeklyHours;
    for (;;) {
      const { days, ranges } = this.parseRule();
      for (const day of days) result[day] = ranges.map((range) => ({ ...range }));
      const token = this.next();
      if (token.kind === "end") return result;
      if (token.kind !== ";") this.unexpected(token, '";" or end of text');
    }
  }

  private parseRule(): { days: Day[]; ranges: TimeRange[] } {
    const days = this.parseDays();
    const token = this.peek();
    if (token.kind === "word" && token.text === "off") {
      this.next();
      return { days, ranges: [] };
    }
    if (token.kind === "time") return { days, ranges: this.parseRanges() };
    return this.unexpected(token, 'a time range, "off" or another day');
  }

  private parseDay(): { day: Day; token: Token } {
    const token = this.next();
    if (token.kind !== "word") this.unexpected(token, "a day");
    if (!(DAYS as readonly string[]).includes(token.text)) {
      throw new OpeningHoursError(
        "UNKNOWN_DAY",
        token.column,
        `Unknown day "${token.text}", expected one of ${DAYS.join(", ")}`,
      );
    }
    return { day: token.text as Day, token };
  }

  private parseDays(): Day[] {
    const days: Day[] = [];
    for (;;) {
      const first = this.parseDay();
      let last = first;
      if (this.peek().kind === "-") {
        this.next();
        last = this.parseDay();
      }
      const item: Day[] = [];
      let index = DAYS.indexOf(first.day);
      for (;;) {
        item.push(DAYS[index]);
        if (DAYS[index] === last.day) break;
        index = (index + 1) % DAYS.length;
      }
      const repeated = item.find((day) => days.includes(day));
      if (repeated) {
        throw new OpeningHoursError("DUPLICATE_DAY", first.token.column, `Day "${repeated}" is named more than once`);
      }
      days.push(...item);
      if (this.peek().kind !== ",") return days;
      this.next();
    }
  }

  private parseTime(isEnd: boolean): { minutes: number; token: Token } {
    const token = this.next();
    if (token.kind !== "time") this.unexpected(token, "a time (HH:MM)");
    const minutes = timeToMinutes(token.text, isEnd);
    if (minutes === null) {
      const hint = token.text === "24:00" ? " (24:00 is only allowed as the end of a range)" : " (expected HH:MM)";
      throw new OpeningHoursError("INVALID_TIME", token.column, `Invalid time "${token.text}"${hint}`);
    }
    return { minutes, token };
  }

  private parseRanges(): TimeRange[] {
    const parsed: { from: number; to: number; range: TimeRange }[] = [];
    for (;;) {
      const start = this.parseTime(false);
      const dash = this.next();
      if (dash.kind !== "-") this.unexpected(dash, '"-"');
      const end = this.parseTime(true);
      if (end.minutes <= start.minutes) {
        throw new OpeningHoursError(
          "END_BEFORE_START",
          start.token.column,
          `Range ${start.token.text}-${end.token.text} must end after it starts`,
        );
      }
      const clash = parsed.find((p) => start.minutes < p.to && p.from < end.minutes);
      if (clash) {
        throw new OpeningHoursError(
          "OVERLAP",
          start.token.column,
          `Range ${start.token.text}-${end.token.text} overlaps ${clash.range.from}-${clash.range.to}`,
        );
      }
      parsed.push({ from: start.minutes, to: end.minutes, range: { from: start.token.text, to: end.token.text } });
      if (this.peek().kind !== ",") break;
      this.next();
    }
    return parsed.sort((a, b) => a.from - b.from).map((p) => p.range);
  }
}

export function parseOpeningHours(text: string): WeeklyHours {
  if (text.trim() === "" && !/[^ ]/.test(text)) {
    throw new OpeningHoursError("EMPTY", 1, "No opening hours given");
  }
  return new Parser(text).parse();
}
