import { parseOpeningHours, type OpeningHoursErrorCode } from "./openingHours";

const closed = { Mo: [], Tu: [], We: [], Th: [], Fr: [], Sa: [], Su: [] };

function expectError(text: string, code: OpeningHoursErrorCode, column: number) {
  let caught: unknown;
  try {
    parseOpeningHours(text);
  } catch (error) {
    caught = error;
  }
  expect(caught).toBeInstanceOf(OpeningHoursError);
  const error = caught as OpeningHoursError;
  expect({ code: error.code, column: error.column }).toEqual({ code, column });
}

test("parses the example", () => {
  const am = { from: "08:00", to: "12:00" };
  const pm = { from: "13:30", to: "18:30" };
  expect(parseOpeningHours("Mo-Fr 08:00-12:00,13:30-18:30; Sa 09:00-16:00; Su off")).toEqual({
    Mo: [am, pm],
    Tu: [am, pm],
    We: [am, pm],
    Th: [am, pm],
    Fr: [am, pm],
    Sa: [{ from: "09:00", to: "16:00" }],
    Su: [],
  });
});

test("day ranges wrap around and single-day ranges work", () => {
  const r = [{ from: "10:00", to: "11:00" }];
  expect(parseOpeningHours("Fr-Mo 10:00-11:00")).toEqual({ ...closed, Fr: r, Sa: r, Su: r, Mo: r });
  expect(parseOpeningHours("Mo-Mo 10:00-11:00")).toEqual({ ...closed, Mo: r });
});

test("spaces are insignificant, ranges sorted, touching allowed, 24:00 end", () => {
  const result = parseOpeningHours("  Mo , We 12:00 - 24:00 ,08:00-12:00  ");
  const r = [
    { from: "08:00", to: "12:00" },
    { from: "12:00", to: "24:00" },
  ];
  expect(result).toEqual({ ...closed, Mo: r, We: r });
});

test("later rules replace earlier ones", () => {
  expect(parseOpeningHours("Mo-Su 08:00-20:00; Su off").Su).toEqual([]);
  const result = parseOpeningHours("Mo-Fr 08:00-12:00; We 14:00-18:00");
  expect(result.We).toEqual([{ from: "14:00", to: "18:00" }]);
  expect(result.Tu).toEqual([{ from: "08:00", to: "12:00" }]);
  expect(result.Sa).toEqual([]);
});

test("each day gets its own array", () => {
  const result = parseOpeningHours("Mo,Tu 08:00-12:00");
  expect(result.Mo).not.toBe(result.Tu);
  expect(result.Mo[0]).not.toBe(result.Tu[0]);
});

